def _sents(v): return [x for x in re.split(r"(?<=[.!?])\s+", re.sub(r"\b(Mt|Dr|St|Mr|Mrs|vs|No)\.\s", r"\1.~", v.strip())) if x]
_FRAG = r"(Point|Ask|Students|A common|Tell|Read|Say|Write|Give|Let|Stop)"
_KEEP = ("True", "False", "BIP39", "BIP32", "HMAC", "Codex32", "SLIP39", "Electrum", "Aezeed")
def _merge(v):
    ss = _sents(v); res = []; i = 0
    while i < len(ss):
        s = ss[i]
        if s.startswith("Ask") and i + 1 < len(ss) and len(ss[i + 1].split()) <= 9 and not re.match(_FRAG, ss[i + 1]):
            a = ss[i + 1]
            if a.split()[0] not in _KEEP and not re.match(r"\d", a): a = a[0].lower() + a[1:]
            res.append(s.rstrip(".?") + "; the answer is " + a); i += 2
        else: res.append(s); i += 1
    return " ".join(res)
for _k in list(NOTES):
    if _k in MANUAL: NOTES[_k] = MANUAL[_k]
    elif len(_sents(NOTES[_k])) > 4: NOTES[_k] = _merge(NOTES[_k])
for _k, _v in NOTES.items(): assert len(_sents(_v)) <= 4 and len(_sents(_v)) >= 2, (_k, len(_sents(_v)))
assert sorted(NOTES) == list(range(1, 69))
for k, v in NOTES.items():
    assert len(v.split()) <= 58, (k, len(v.split()))
